class User {
  String user,name,role,hash,photo;
  User(this.user,this.name,this.role,this.hash,{this.photo=''});
  Map<String,dynamic> json()=>{'user':user,'name':name,'role':role,'hash':hash,'photo':photo};
  factory User.from(Map<String,dynamic> j)=>User(j['user']??'',j['name']??'',j['role']??'',j['hash']??'',photo:j['photo']??'');
}
class Occ {
  String id,date,time,farm='',plot='',operation='',employee='',role='',type='',body='',desc='',animal='',hospital='',status='Em análise';
  List<String> attendance=[],causes=[],photos=[]; double lat=0,lng=0,accuracy=0;
  Occ(this.id,this.date,this.time);
  Map<String,dynamic> json()=>{'id':id,'date':date,'time':time,'farm':farm,'plot':plot,'operation':operation,'employee':employee,'role':role,'type':type,'body':body,'desc':desc,'animal':animal,'hospital':hospital,'status':status,'attendance':attendance,'causes':causes,'photos':photos,'lat':lat,'lng':lng,'accuracy':accuracy};
  factory Occ.from(Map<String,dynamic> j){final o=Occ(j['id']??'',j['date']??'',j['time']??'');o.farm=j['farm']??'';o.plot=j['plot']??'';o.operation=j['operation']??'';o.employee=j['employee']??'';o.role=j['role']??'';o.type=j['type']??'';o.body=j['body']??'';o.desc=j['desc']??'';o.animal=j['animal']??'';o.hospital=j['hospital']??'';o.status=j['status']??'Em análise';o.attendance=List<String>.from(j['attendance']??[]);o.causes=List<String>.from(j['causes']??[]);o.photos=List<String>.from(j['photos']??[]);o.lat=(j['lat']??0).toDouble();o.lng=(j['lng']??0).toDouble();o.accuracy=(j['accuracy']??0).toDouble();return o;}
}
class Report {String id,title,text;Report(this.id,this.title,this.text);Map<String,dynamic> json()=>{'id':id,'title':title,'text':text};factory Report.from(Map<String,dynamic> j)=>Report(j['id'],j['title'],j['text']);}
 
class Store extends ChangeNotifier {
  Store._(); static final i=Store._(); List<User> users=[];List<Occ> occ=[];List<Report> reports=[];User? current;
  String h(String s)=>sha256.convert(utf8.encode(s)).toString();
  Future<void> load()async{final p=await SharedPreferences.getInstance();users=(jsonDecode(p.getString('users')??'[]')as List).map((e)=>User.from(Map<String,dynamic>.from(e))).toList();occ=(jsonDecode(p.getString('occ')??'[]')as List).map((e)=>Occ.from(Map<String,dynamic>.from(e))).toList();reports=(jsonDecode(p.getString('reports')??'[]')as List).map((e)=>Report.from(Map<String,dynamic>.from(e))).toList();final u=p.getString('logged');for(final x in users){if(x.user==u)current=x;}}
  Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('users',jsonEncode(users.map((e)=>e.json()).toList()));await p.setString('occ',jsonEncode(occ.map((e)=>e.json()).toList()));await p.setString('reports',jsonEncode(reports.map((e)=>e.json()).toList()));if(current==null)await p.remove('logged');else await p.setString('logged',current!.user);notifyListeners();}
  Future<String?> register(String u,String pw,String n,String r)async{if(u.trim().isEmpty||n.trim().isEmpty||pw.length<4)return'Preencha os campos. A senha deve ter 4 caracteres ou mais.';if(users.any((x)=>x.user.toLowerCase()==u.trim().toLowerCase()))return'Usuário já existe.';users.add(User(u.trim(),n.trim(),r.trim(),h(pw)));await save();return null;}
  Future<bool> login(String u,String pw)async{for(final x in users){if(x.user.toLowerCase()==u.trim().toLowerCase()&&x.hash==h(pw)){current=x;await save();return true;}}return false;}
  Future<void> logout()async{current=null;await save();}
}
 
// ===== Lista de colaboradores (salva no aparelho) =====
class ColabStore{
  static Future<List<String>> list()async{final p=await SharedPreferences.getInstance();final l=List<String>.from(p.getStringList('colaboradores')??[]);l.sort((a,b)=>a.toLowerCase().compareTo(b.toLowerCase()));return l;}
  static Future<void> add(String n)async{final v=n.trim();if(v.isEmpty)return;final p=await SharedPreferences.getInstance();final l=List<String>.from(p.getStringList('colaboradores')??[]);if(!l.any((e)=>e.toLowerCase()==v.toLowerCase())){l.add(v);await p.setStringList('colaboradores',l);}}
  static Future<void> remove(String n)async{final p=await SharedPreferences.getInstance();final l=List<String>.from(p.getStringList('colaboradores')??[]);l.remove(n);await p.setStringList('colaboradores',l);}
}
class CampoColab extends StatefulWidget{
  final TextEditingController controller;
  const CampoColab({super.key,required this.controller});
  @override State<CampoColab> createState()=>_CampoColabState();
