class _CampoColabState extends State<CampoColab>{
  final focus=FocusNode();
  List<String> nomes=[];
  @override void initState(){super.initState();carregar();focus.addListener((){if(focus.hasFocus)carregar();});}
  @override void dispose(){focus.dispose();super.dispose();}
  Future<void> carregar()async{final l=await ColabStore.list();if(mounted)setState(()=>nomes=l);}
  @override Widget build(BuildContext context)=>RawAutocomplete<String>(
    textEditingController:widget.controller,
    focusNode:focus,
    optionsBuilder:(v){return v.text.isEmpty?nomes:nomes.where((n)=>n.toLowerCase().contains(v.text.toLowerCase()));},
    fieldViewBuilder:(context,c,f,s)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,focusNode:f,textCapitalization:TextCapitalization.words,decoration:const InputDecoration(labelText:'Funcionário envolvido',suffixIcon:Icon(Icons.arrow_drop_down)))),
    optionsViewBuilder:(context,onSelected,options)=>Align(alignment:Alignment.topLeft,child:Material(elevation:4,borderRadius:BorderRadius.circular(12),child:ConstrainedBox(constraints:const BoxConstraints(maxHeight:220,maxWidth:340),child:ListView(padding:EdgeInsets.zero,shrinkWrap:true,children:options.map((n)=>ListTile(dense:true,title:Text(n),trailing:IconButton(tooltip:'Remover da lista',icon:const Icon(Icons.close,size:18),onPressed:()async{await ColabStore.remove(n);await carregar();}),onTap:()=>onSelected(n))).toList())))),
  );
}
 
