// ===== Configurações: editar, apagar e resetar relatórios/ocorrências =====
class Configuracoes extends StatefulWidget{const Configuracoes({super.key});@override State<Configuracoes> createState()=>_ConfiguracoesState();}
class _ConfiguracoesState extends State<Configuracoes>{
  Future<bool> confirmar(String t,String m)async{final r=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:Text(t),content:Text(m),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancelar')),ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Colors.red,foregroundColor:Colors.white),onPressed:()=>Navigator.pop(d,true),child:const Text('Confirmar'))]));return r==true;}
  void aviso(String s){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));}
 
  Future<void> editarRel(Report r)async{
    final t=TextEditingController(text:r.title),x=TextEditingController(text:r.text);
    final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Editar relatório'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:t,decoration:const InputDecoration(labelText:'Título')),const SizedBox(height:10),TextField(controller:x,maxLines:12,decoration:const InputDecoration(labelText:'Texto do relatório'))])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancelar')),ElevatedButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Salvar'))]));
    if(ok==true){if(t.text.trim().isNotEmpty)r.title=t.text.trim();r.text=x.text;await Store.i.save();if(mounted){setState((){});aviso('Relatório atualizado.');}}
  }
  Future<void> apagarRel(Report r)async{if(await confirmar('Apagar relatório','Deseja apagar "${r.title}"? Esta ação não pode ser desfeita.')){Store.i.reports.remove(r);await Store.i.save();if(mounted)setState((){});}}
  Future<void> resetRel()async{if(await confirmar('Resetar relatórios','Todos os relatórios salvos serão apagados de uma só vez. Deseja continuar?')){Store.i.reports.clear();await Store.i.save();if(mounted){setState((){});aviso('Todos os relatórios foram apagados.');}}}
 
  Future<void> editarOcc(Occ o)async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>NewOcc(o:Occ.from(o.json()),edit:true)));if(mounted)setState((){});}
  Future<void> apagarOcc(Occ o)async{if(await confirmar('Apagar ocorrência','Deseja apagar esta ocorrência (${o.date} - ${o.type.isEmpty?'Ocorrência':o.type})? Esta ação não pode ser desfeita.')){Store.i.occ.removeWhere((x)=>x.id==o.id);await Store.i.save();if(mounted)setState((){});}}
  Future<void> resetOcc()async{if(await confirmar('Resetar ocorrências','Todas as ocorrências serão apagadas de uma só vez e os contadores do início voltam a zero. Deseja continuar?')){Store.i.occ.clear();await Store.i.save();if(mounted){setState((){});aviso('Todas as ocorrências foram apagadas.');}}}
 
  Widget acoes(VoidCallback editar,VoidCallback apagar)=>Row(mainAxisSize:MainAxisSize.min,children:[IconButton(tooltip:'Editar',icon:const Icon(Icons.edit),onPressed:editar),IconButton(tooltip:'Apagar',icon:const Icon(Icons.delete,color:Colors.red),onPressed:apagar)]);
  Widget rodape(String label,bool vazio,VoidCallback f)=>SafeArea(child:Padding(padding:const EdgeInsets.all(12),child:SizedBox(width:double.infinity,child:OutlinedButton.icon(style:OutlinedButton.styleFrom(foregroundColor:Colors.red,side:const BorderSide(color:Colors.red),padding:const EdgeInsets.symmetric(vertical:14)),icon:const Icon(Icons.delete_forever),label:Text(label),onPressed:vazio?null:f))));
 
  Widget tabRel(){final l=Store.i.reports;return Column(children:[Expanded(child:l.isEmpty?const Center(child:Text('Nenhum relatório salvo.')):ListView(padding:const EdgeInsets.all(8),children:l.map((r)=>Card(child:ListTile(leading:const Icon(Icons.description,color:green),title:Text(r.title),trailing:acoes(()=>editarRel(r),()=>apagarRel(r))))).toList())),rodape('Resetar relatórios (apagar todos)',l.isEmpty,resetRel)]);}
  Widget tabOcc(){final l=Store.i.occ;return Column(children:[Expanded(child:l.isEmpty?const Center(child:Text('Nenhuma ocorrência registrada.')):ListView(padding:const EdgeInsets.all(8),children:l.map((o)=>Card(child:ListTile(leading:const Icon(Icons.report,color:green),title:Text(o.type.isEmpty?'Ocorrência':o.type),subtitle:Text('${o.date} • ${o.employee}\n${o.farm}'),isThreeLine:true,trailing:acoes(()=>editarOcc(o),()=>apagarOcc(o))))).toList())),rodape('Resetar ocorrências (apagar todas)',l.isEmpty,resetOcc)]);}
 
  @override Widget build(BuildContext c)=>DefaultTabController(length:2,child:Scaffold(appBar:const Bar(title:'Configurações'),body:Column(children:[const Material(color:Colors.white,child:TabBar(labelColor:darkGreen,indicatorColor:green,tabs:[Tab(icon:Icon(Icons.description),text:'Relatórios'),Tab(icon:Icon(Icons.list_alt),text:'Ocorrências')])),Expanded(child:TabBarView(children:[tabRel(),tabOcc()]))])));
}
 
