class _NewOccState extends State<NewOcc>{int step=0;final farm=TextEditingController(),plot=TextEditingController(),op=TextEditingController(),desc=TextEditingController(),hospital=TextEditingController(),emp=TextEditingController(),rol=TextEditingController();@override void initState(){super.initState();farm.text=widget.o.farm;plot.text=widget.o.plot;op.text=widget.o.operation;desc.text=widget.o.desc;hospital.text=widget.o.hospital;emp.text=widget.o.employee;rol.text=widget.o.role;}void sync(){widget.o.farm=farm.text;widget.o.plot=plot.text;widget.o.operation=op.text;widget.o.desc=desc.text;widget.o.hospital=hospital.text;widget.o.employee=emp.text.trim();widget.o.role=rol.text.trim();}Widget inp(String s,TextEditingController c)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,maxLines:s.startsWith('Descrição')?4:1,decoration:InputDecoration(labelText:s)));
Future<void> gps()async{if(!await Geolocator.isLocationServiceEnabled())return;var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever)return;final z=await Geolocator.getCurrentPosition(desiredAccuracy:LocationAccuracy.high);if(mounted)setState((){widget.o.lat=z.latitude;widget.o.lng=z.longitude;widget.o.accuracy=z.accuracy;});}
