Widget accident(String s,IconData i){final on=widget.o.type==s;return InkWell(onTap:()=>setState(()=>widget.o.type=s),child:Container(decoration:BoxDecoration(color:on?paleGreen:Colors.grey.shade100,border:Border.all(color:on?green:Colors.grey.shade300),borderRadius:BorderRadius.circular(9)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(i,color:on?green:Colors.red,size:29),Text(s,textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.bold))])));}
Widget check(String s,List<String> l)=>CheckboxListTile(contentPadding:EdgeInsets.zero,dense:true,value:l.contains(s),title:Text(s),onChanged:(v)=>setState((){if(v==true){if(!l.contains(s))l.add(s);}else l.remove(s);}));
Future<void> finalizar(BuildContext c)async{
  await ColabStore.add(emp.text);
  if(widget.edit){
    final i=Store.i.occ.indexWhere((x)=>x.id==widget.o.id);
    if(i>=0)Store.i.occ[i]=widget.o;
    await Store.i.save();
    if(c.mounted){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Ocorrência atualizada.')));Navigator.pop(c);}
  }else{
    Store.i.occ.insert(0,widget.o);
    await Store.i.save();
    if(c.mounted)Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>ReportPage(o:widget.o)));
  }
}
@override Widget build(BuildContext c){final titles=['1. Dados Gerais','2. Detalhes','3. Fotos e Localização','4. Atendimento e Causas','5. Revisão'];return Scaffold(appBar:Bar(title:widget.edit?'Editar Ocorrência':'Nova Ocorrência'),body:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(18,18,18,5),child:Dots(step)),Text(titles[step],style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold)),Expanded(child:SingleChildScrollView(padding:const EdgeInsets.all(16),child:[general(),details(),photos(),causes(),review()][step])),Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:OutlinedButton(onPressed:(){if(step==0)Navigator.pop(c);else setState(()=>step--);},child:const Text('Voltar'))),const SizedBox(width:8),Expanded(child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:green,foregroundColor:Colors.white),onPressed:()async{sync();if(step<4)setState(()=>step++);else await finalizar(c);},child:Text(step==4?(widget.edit?'Salvar alterações':'Salvar ocorrência'):'Próximo')))]))]));}
