String report(Occ o)=>'''SAFE FOREST - G.E.R.S. FLORESTAL
RELATÓRIO DE OCORRÊNCIA
 
Data/Hora: ${o.date} - ${o.time}
Local: ${o.farm} - ${o.plot}
Empresa: G.E.R.S. FLORESTAL
Funcionário: ${o.employee}
Função: ${o.role}
Operação: ${o.operation}
Tipo de acidente: ${o.type}
${o.animal.isNotEmpty?'Animal envolvido: ${o.animal}\n':''}Parte atingida: ${o.body}
Descrição: ${o.desc}
Atendimento: ${o.attendance.join(', ')}
Unidade: ${o.hospital}
Possíveis causas: ${o.causes.join(', ')}
Latitude: ${o.lat}
Longitude: ${o.lng}
Precisão GPS: ${o.accuracy.toStringAsFixed(1)} m
Status: ${o.status}
''';
class ReportPage extends StatelessWidget{final Occ o;const ReportPage({super.key,required this.o});Future<void> save(BuildContext c)async{final t=report(o);Store.i.reports.insert(0,Report(DateTime.now().microsecondsSinceEpoch.toString(),'${o.date} - ${o.type}',t));await Store.i.save();final d=await getApplicationDocumentsDirectory();await File('${d.path}/relatorio_${o.id}.txt').writeAsString(t);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Relatório salvo dentro do aplicativo.')));}Future<void> share()async=>SharePlus.instance.share(ShareParams(text:report(o),subject:'Relatório Safe Forest - ${o.date}'));@override Widget build(BuildContext c)=>Scaffold(appBar:const Bar(title:'Relatório de Ocorrência'),body:ListView(padding:const EdgeInsets.all(16),children:[const Logo(h:90),const Center(child:Text('G.E.R.S. FLORESTAL',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18))),const Divider(),SelectableText(report(o),style:const TextStyle(fontSize:16,height:1.45)),Row(children:[Expanded(child:ElevatedButton.icon(onPressed:share,icon:const Icon(Icons.share),label:const Text('Compartilhar'))),const SizedBox(width:8),Expanded(child:OutlinedButton.icon(onPressed:()=>save(c),icon:const Icon(Icons.save),label:const Text('Salvar')))])]));}
